const input = $input.first().json;
const body = input.body ?? input;
console.log('Body recibido:', JSON.stringify(body));
let leadId = null;
for (const key of Object.keys(body)) {
  const match = key.match(/^leads\[(add|update|status|responsible|delete)\]\[(\d+)\]\[id\]$/);
  if (match) { leadId = parseInt(body[key], 10); break; }
}
if (!leadId && body.leads?.add?.[0]?.id) leadId = parseInt(body.leads.add[0].id, 10);
if (!leadId && body.leads?.update?.[0]?.id) leadId = parseInt(body.leads.update[0].id, 10);
if (!leadId && body.lead_id) leadId = parseInt(body.lead_id, 10);
if (!leadId && body.id) leadId = parseInt(body.id, 10);
if (!leadId || isNaN(leadId)) throw new Error('No se pudo extraer lead_id. Keys: ' + JSON.stringify(Object.keys(body)));
return [{ json: { lead_id: leadId } }];

// =============================================================
// VALIDAR ABONOS Y DECIDIR ACCION (v6 - con fix partial + defensas)
// =============================================================

const FIELD_ABONOS = [
  1047219, 1047223, 1047229, 1047237,
  1047243, 1047251, 1047257, 1047263,
  1047269, 1047275, 1047281, 1047287,
  1047293, 1047299, 1047305, 1047311
];
const FIELD_MONTO_PENDIENTE = 1047205;
const FIELD_FECHA_COBRO = 1046747;
const FIELD_FECHA_PAGO = 1046553;
const FIELD_DIAS_VENCIDO = 1046603;
const FIELD_TIPO_CREDITO = 1046741;
const FIELD_ESTADO_CREDITO = 1047207;
const FIELD_VALOR_COTIZADO = 1046505;
const FIELD_VALOR_CUOTA = 1047317;
const FIELD_CUOTAS_PAGADAS = 1047319;

const STAGE_CREDITO_ACTIVO = 109770728;
const TIPOS_RECURRENTES = ['12 Meses', '16 Meses'];
const DIAS_POR_CUOTA = 30;
const TOTAL_CUOTAS_POR_TIPO = { '12 Meses': 12, '16 Meses': 16 };

let lead = $input.first().json;
if (lead.data && typeof lead.data === 'string') {
  try { lead = JSON.parse(lead.data); } catch (e) { throw new Error('No se pudo parsear lead: ' + e.message); }
}

function getFieldValue(fieldId) {
  const f = lead.custom_fields_values?.find(x => x.field_id === fieldId);
  if (!f || !f.values || f.values.length === 0) return null;
  return f.values[0].value;
}

function parseNum(valor) {
  if (valor === null || valor === undefined) return 0;
  if (typeof valor === 'number') return Number.isFinite(valor) ? valor : 0;
  if (typeof valor === 'object') return 0;
  const s = String(valor).replace(/[$\s]/g, '').trim();
  if (s === '' || s === '()' || s === '-') return 0;
  const tieneComa = s.includes(',');
  const tienePunto = s.includes('.');
  let n;
  if (tieneComa && tienePunto) {
    if (s.lastIndexOf(',') > s.lastIndexOf('.')) n = Number(s.split('.').join('').replace(',', '.'));
    else n = Number(s.split(',').join(''));
  } else if (tieneComa) {
    const partes = s.split(',');
    const esMiles = partes.slice(1).every(p => p.length === 3) && partes[0].length <= 3;
    n = esMiles ? Number(partes.join('')) : Number(s.replace(',', '.'));
  } else { n = Number(s); }
  return Number.isFinite(n) ? n : 0;
}

const fechaPagoHoy = Math.floor(Date.now() / 1000);

console.log('========== DEBUG ==========');
console.log('Lead ID:', lead.id, '-', lead.name);
console.log('Tipo credito:', getFieldValue(FIELD_TIPO_CREDITO));
console.log('Valor cuota (raw):', getFieldValue(FIELD_VALOR_CUOTA));
console.log('Cuotas pagadas (raw):', getFieldValue(FIELD_CUOTAS_PAGADAS));
console.log('Monto pendiente (raw):', getFieldValue(FIELD_MONTO_PENDIENTE));
console.log('Valor cotizado (raw):', getFieldValue(FIELD_VALOR_COTIZADO));

// GUARDIA 1: ya liquidado
const estadoActual = getFieldValue(FIELD_ESTADO_CREDITO);
if (estadoActual === 'Liquidado') {
  console.log('-> GUARDIA: ya liquidado');
  return [{ json: {
    lead_id: lead.id, lead_name: lead.name,
    accion: 'already_liquidated',
    mensaje: 'Este credito ya estaba liquidado. No se hace nada.',
    saldo: 0, total_abonado: 0, monto_original: 0, abonos_registrados: 0,
    tipo_credito: '', cuotas_nuevas: 0, cuotas_totales_hoy: 0, dias_sumar: 0,
    fecha_pago_hoy: fechaPagoHoy,
    field_fecha_cobro: FIELD_FECHA_COBRO, field_monto_pendiente: FIELD_MONTO_PENDIENTE,
    field_fecha_pago: FIELD_FECHA_PAGO,
    field_estado_credito: FIELD_ESTADO_CREDITO, field_dias_vencido: FIELD_DIAS_VENCIDO,
    field_cuotas_pagadas: FIELD_CUOTAS_PAGADAS, stage_credito_activo: STAGE_CREDITO_ACTIVO,
    nueva_fecha_cobro: 0
  }}];
}

// 1. Sumar abonos
let totalAbonado = 0;
let abonosRegistrados = 0;
const abonosDebug = [];
for (const id of FIELD_ABONOS) {
  const raw = getFieldValue(id);
  const valor = parseNum(raw);
  if (raw !== null && raw !== undefined && raw !== '') {
    abonosDebug.push(`  Abono ${id}: raw="${raw}" -> parsed=${valor}`);
  }
  if (valor > 0) { totalAbonado += valor; abonosRegistrados++; }
}
console.log('Abonos no vacios:');
console.log(abonosDebug.join('\n') || '  (ninguno)');
console.log('Total abonado:', totalAbonado, '| Abonos registrados:', abonosRegistrados);

// 2. Monto original
const montoPendienteManual = parseNum(getFieldValue(FIELD_MONTO_PENDIENTE));
const montoValorCotizado = parseNum(getFieldValue(FIELD_VALOR_COTIZADO));
const montoPriceNativo = parseNum(lead.price);
const montoOriginal = Math.max(montoPendienteManual, montoValorCotizado, montoPriceNativo);
console.log('Monto original (max):', montoOriginal);

// GUARDIA 2: monto invalido
if (montoOriginal <= 0) {
  console.log('-> GUARDIA: monto original invalido');
  return [{ json: {
    lead_id: lead.id, lead_name: lead.name,
    accion: 'error',
    mensaje: 'El lead no tiene monto original. Verifica Valor Cotizado o Presupuesto.',
    saldo: 0, total_abonado: totalAbonado, monto_original: 0, abonos_registrados: abonosRegistrados,
    tipo_credito: '', cuotas_nuevas: 0, cuotas_totales_hoy: 0, dias_sumar: 0,
    fecha_pago_hoy: fechaPagoHoy,
    field_fecha_cobro: FIELD_FECHA_COBRO, field_monto_pendiente: FIELD_MONTO_PENDIENTE,
    field_fecha_pago: FIELD_FECHA_PAGO,
    field_estado_credito: FIELD_ESTADO_CREDITO, field_dias_vencido: FIELD_DIAS_VENCIDO,
    field_cuotas_pagadas: FIELD_CUOTAS_PAGADAS, stage_credito_activo: STAGE_CREDITO_ACTIVO,
    nueva_fecha_cobro: 0
  }}];
}

// 3. Calcular saldo
const saldo = montoOriginal - totalAbonado;

// 4. Tipo de credito
const tipoCredito = getFieldValue(FIELD_TIPO_CREDITO) || '30 Días';
const esRecurrente = TIPOS_RECURRENTES.includes(tipoCredito);
const valorCuota = parseNum(getFieldValue(FIELD_VALOR_CUOTA));
let cuotasPrevias = parseNum(getFieldValue(FIELD_CUOTAS_PAGADAS));

console.log('esRecurrente:', esRecurrente);
console.log('valorCuota:', valorCuota);
console.log('cuotasPrevias (raw del campo):', cuotasPrevias);

// DEFENSA 1: si cuotasPrevias > 0 pero totalAbonado = 0 -> reset
if (cuotasPrevias > 0 && totalAbonado === 0) {
  console.log('⚠️ DEFENSA 1: cuotasPrevias > 0 pero totalAbonado = 0. Reseteando a 0.');
  cuotasPrevias = 0;
}

// DEFENSA 2: si es recurrente pero valorCuota es 0, error
if (esRecurrente && valorCuota <= 0) {
  console.log('-> GUARDIA: recurrente sin valor de cuota');
  return [{ json: {
    lead_id: lead.id, lead_name: lead.name,
    accion: 'error',
    mensaje: `[${tipoCredito}] El campo 'Valor de Cuota' esta vacio o es 0. No se puede calcular.`,
    saldo: saldo, total_abonado: totalAbonado, monto_original: montoOriginal, abonos_registrados: abonosRegistrados,
    tipo_credito: tipoCredito, cuotas_nuevas: 0, cuotas_totales_hoy: cuotasPrevias, dias_sumar: 0,
    fecha_pago_hoy: fechaPagoHoy,
    field_fecha_cobro: FIELD_FECHA_COBRO, field_monto_pendiente: FIELD_MONTO_PENDIENTE,
    field_fecha_pago: FIELD_FECHA_PAGO,
    field_estado_credito: FIELD_ESTADO_CREDITO, field_dias_vencido: FIELD_DIAS_VENCIDO,
    field_cuotas_pagadas: FIELD_CUOTAS_PAGADAS, stage_credito_activo: STAGE_CREDITO_ACTIVO,
    nueva_fecha_cobro: 0
  }}];
}

// 5. Cuotas completadas (solo recurrentes)
let cuotasNuevas = 0;
let cuotasTotalesHoy = cuotasPrevias;
let diasSumar = 0;

if (esRecurrente && valorCuota > 0) {
  // Cuantas cuotas se han completado segun el total abonado
  const cuotasCalculadas = Math.floor(totalAbonado / valorCuota);

  // DEFENSA 3: si el campo dice mas cuotas que las calculadas, usar el calculado
  if (cuotasPrevias > cuotasCalculadas) {
    console.log(`⚠️ DEFENSA 3: campo dice ${cuotasPrevias} cuotas, calculadas ${cuotasCalculadas}. Usando ${Math.max(0, cuotasCalculadas - 1)}.`);
    cuotasPrevias = Math.max(0, cuotasCalculadas - 1);
  }

  cuotasTotalesHoy = cuotasCalculadas;
  cuotasNuevas = Math.max(0, cuotasTotalesHoy - cuotasPrevias);
  diasSumar = cuotasNuevas * DIAS_POR_CUOTA;

  console.log('cuotasCalculadas (floor(totalAbonado/valorCuota)):', cuotasCalculadas);
  console.log('cuotasPrevias (final):', cuotasPrevias);
  console.log('cuotasNuevas:', cuotasNuevas);
  console.log('diasSumar:', diasSumar);
}

// 6. Nueva fecha de cobro
const fechaCobroActual = getFieldValue(FIELD_FECHA_COBRO);
const fechaBase = fechaCobroActual ? new Date(fechaCobroActual * 1000) : new Date();
const nuevaFecha = new Date(fechaBase);
nuevaFecha.setDate(nuevaFecha.getDate() + diasSumar);
const nuevaFechaTimestamp = Math.floor(nuevaFecha.getTime() / 1000);

// 7. Decidir accion
let accion, mensaje, motivo;

if (saldo > 0.01) {
  if (esRecurrente) {
    if (cuotasNuevas > 0) {
      accion = 'restart';
      motivo = 'Completo cuota(s) nueva(s). Avanza fecha de cobro.';
      mensaje = `[${tipoCredito}] Ciclo avanzado +${cuotasNuevas} cuota(s) (+${diasSumar} dias). Total abonado: $${totalAbonado.toFixed(2)}, Saldo: $${saldo.toFixed(2)}. Proximo cobro: ${nuevaFecha.toISOString().split('T')[0]}`;
    } else {
      accion = 'partial_recurrent';
      motivo = 'Abono parcial. No completa cuota. Devuelve a CREDITO ACTIVO sin cambiar fecha.';
      mensaje = `[${tipoCredito}] Abono parcial (aun no completa cuota). Total abonado: $${totalAbonado.toFixed(2)}, Cuota: $${valorCuota.toFixed(2)}, Saldo: $${saldo.toFixed(2)}. Fecha de cobro SIN cambios. Devuelto a CREDITO ACTIVO.`;
    }
  } else {
    accion = 'partial_single';
    motivo = 'Credito de pago unico con abono parcial. Devuelve a CREDITO ACTIVO sin cambiar fecha.';
    mensaje = `[${tipoCredito}] Abono parcial registrado. Total abonado: $${totalAbonado.toFixed(2)}, Saldo: $${saldo.toFixed(2)}. Fecha de cobro SIN cambios. Devuelto a CREDITO ACTIVO.`;
  }
} else if (saldo < -0.01) {
  accion = 'overpaid';
  motivo = 'El cliente pago mas del saldo. Alerta.';
  mensaje = `ALERTA: El cliente pago de mas. Total abonado: $${totalAbonado.toFixed(2)}, Monto original: $${montoOriginal.toFixed(2)}, Diferencia: $${Math.abs(saldo).toFixed(2)}`;
} else {
  accion = 'liquidate';
  motivo = 'Saldo en 0. Credito liquidado.';
  mensaje = `[${tipoCredito}] Credito LIQUIDADO. Total pagado: $${totalAbonado.toFixed(2)} en ${abonosRegistrados} abonos.`;
}

console.log('ACCION FINAL:', accion);
console.log('MOTIVO:', motivo);
console.log('========== FIN DEBUG ==========');

return [{ json: {
  lead_id: lead.id,
  lead_name: lead.name,
  accion: accion,
  motivo: motivo,
  mensaje: mensaje,
  monto_original: montoOriginal,
  total_abonado: totalAbonado,
  abonos_registrados: abonosRegistrados,
  saldo: saldo,
  tipo_credito: tipoCredito,
  es_recurrente: esRecurrente,
  valor_cuota: valorCuota,
  cuotas_previas: cuotasPrevias,
  cuotas_nuevas: cuotasNuevas,
  cuotas_totales_hoy: cuotasTotalesHoy,
  dias_sumar: diasSumar,
  fecha_pago_hoy: fechaPagoHoy,
  nueva_fecha_cobro: nuevaFechaTimestamp,
  field_fecha_cobro: FIELD_FECHA_COBRO,
  field_monto_pendiente: FIELD_MONTO_PENDIENTE,
  field_fecha_pago: FIELD_FECHA_PAGO,
  field_estado_credito: FIELD_ESTADO_CREDITO,
  field_dias_vencido: FIELD_DIAS_VENCIDO,
  field_cuotas_pagadas: FIELD_CUOTAS_PAGADAS,
  stage_credito_activo: STAGE_CREDITO_ACTIVO
}}];

